CREATE TABLE IF NOT EXISTS c_accounts (_id TEXT PRIMARY KEY NOT NULL, accountId TEXT, data TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS i_accounts__accountId ON c_accounts (accountId);
CREATE UNIQUE INDEX IF NOT EXISTS u_accounts__ownerId ON c_accounts (json_extract(data, '$.ownerId') ASC);
CREATE UNIQUE INDEX IF NOT EXISTS u_accounts__stripeCustomerId ON c_accounts (json_extract(data, '$.stripeCustomerId') ASC) WHERE json_type(data, '$.stripeCustomerId') = 'text';
CREATE INDEX IF NOT EXISTS i_accounts__stripeSubscriptionId ON c_accounts (json_extract(data, '$.stripeSubscriptionId') ASC) WHERE json_type(data, '$.stripeSubscriptionId') = 'text';
CREATE INDEX IF NOT EXISTS i_accounts__createdAt_d ON c_accounts (json_extract(data, '$.createdAt') DESC);
CREATE UNIQUE INDEX IF NOT EXISTS u_accounts__ses_tenantName ON c_accounts (json_extract(data, '$.ses.tenantName') ASC) WHERE json_type(data, '$.ses.tenantName') = 'text';
CREATE UNIQUE INDEX IF NOT EXISTS u_accounts__postshiba_tenantSlug ON c_accounts (json_extract(data, '$.postshiba.tenantSlug') ASC) WHERE json_type(data, '$.postshiba.tenantSlug') = 'text';
CREATE TABLE IF NOT EXISTS c_alerts (_id TEXT PRIMARY KEY NOT NULL, accountId TEXT, data TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS i_alerts__accountId ON c_alerts (accountId);
CREATE UNIQUE INDEX IF NOT EXISTS u_alerts__accountId__key ON c_alerts (IFNULL(accountId, '') ASC, json_extract(data, '$.key') ASC);
CREATE TABLE IF NOT EXISTS c_apikeys (_id TEXT PRIMARY KEY NOT NULL, accountId TEXT, data TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS i_apikeys__accountId ON c_apikeys (accountId);
CREATE UNIQUE INDEX IF NOT EXISTS u_apikeys__hash ON c_apikeys (json_extract(data, '$.hash') ASC);
CREATE INDEX IF NOT EXISTS i_apikeys__accountId__createdAt_d ON c_apikeys (accountId ASC, json_extract(data, '$.createdAt') DESC);
CREATE TABLE IF NOT EXISTS c_campaigns (_id TEXT PRIMARY KEY NOT NULL, accountId TEXT, data TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS i_campaigns__accountId ON c_campaigns (accountId);
CREATE INDEX IF NOT EXISTS i_campaigns__newsletterId__createdAt_d ON c_campaigns (json_extract(data, '$.newsletterId') ASC, json_extract(data, '$.createdAt') DESC);
CREATE INDEX IF NOT EXISTS i_campaigns__accountId__status ON c_campaigns (accountId ASC, json_extract(data, '$.status') ASC);
CREATE INDEX IF NOT EXISTS i_campaigns__newsletterId__startedAt_d ON c_campaigns (json_extract(data, '$.newsletterId') ASC, json_extract(data, '$.startedAt') DESC);
CREATE UNIQUE INDEX IF NOT EXISTS u_campaigns__archiveSlug ON c_campaigns (json_extract(data, '$.archiveSlug') ASC) WHERE json_type(data, '$.archiveSlug') = 'text';
CREATE TABLE IF NOT EXISTS c_contacts (_id TEXT PRIMARY KEY NOT NULL, accountId TEXT, data TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS i_contacts__accountId ON c_contacts (accountId);
CREATE UNIQUE INDEX IF NOT EXISTS u_contacts__newsletterId__email ON c_contacts (json_extract(data, '$.newsletterId') ASC, json_extract(data, '$.email') ASC);
CREATE INDEX IF NOT EXISTS i_contacts__newsletterId__status__createdAt_d ON c_contacts (json_extract(data, '$.newsletterId') ASC, json_extract(data, '$.status') ASC, json_extract(data, '$.createdAt') DESC);
CREATE INDEX IF NOT EXISTS i_contacts__accountId__email ON c_contacts (accountId ASC, json_extract(data, '$.email') ASC);
CREATE INDEX IF NOT EXISTS i_contacts__accountId__subscribedAt_d___id_d ON c_contacts (accountId ASC, json_extract(data, '$.subscribedAt') DESC, _id DESC);
CREATE INDEX IF NOT EXISTS i_contacts__accountId__status__subscribedAt_d___id_d ON c_contacts (accountId ASC, json_extract(data, '$.status') ASC, json_extract(data, '$.subscribedAt') DESC, _id DESC);
CREATE INDEX IF NOT EXISTS i_contacts__newsletterId__subscribedAt_d___id_d ON c_contacts (json_extract(data, '$.newsletterId') ASC, json_extract(data, '$.subscribedAt') DESC, _id DESC);
CREATE INDEX IF NOT EXISTS i_contacts__newsletterId__status__subscribedAt_d___id_d ON c_contacts (json_extract(data, '$.newsletterId') ASC, json_extract(data, '$.status') ASC, json_extract(data, '$.subscribedAt') DESC, _id DESC);
CREATE INDEX IF NOT EXISTS i_contacts__newsletterId__lastChanceAt ON c_contacts (json_extract(data, '$.newsletterId') ASC, json_extract(data, '$.lastChanceAt') ASC) WHERE json_type(data, '$.lastChanceAt') IS NOT NULL;
CREATE INDEX IF NOT EXISTS i_contacts__email ON c_contacts (json_extract(data, '$.email') ASC) WHERE json_type(data, '$.undeliverableAt') IS NOT NULL;
CREATE TABLE IF NOT EXISTS c_contactimports (_id TEXT PRIMARY KEY NOT NULL, accountId TEXT, data TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS i_contactimports__accountId ON c_contactimports (accountId);
