CREATE INDEX IF NOT EXISTS i_deletionrecords__accountId ON c_deletionrecords (accountId);
CREATE UNIQUE INDEX IF NOT EXISTS u_deletionrecords__accountId ON c_deletionrecords (accountId ASC);
CREATE INDEX IF NOT EXISTS i_deletionrecords__emailHash ON c_deletionrecords (json_extract(data, '$.emailHash') ASC);
