CREATE INDEX IF NOT EXISTS i_domains__accountId ON c_domains (accountId);
CREATE UNIQUE INDEX IF NOT EXISTS u_domains__domain ON c_domains (json_extract(data, '$.domain') ASC);
CREATE UNIQUE INDEX IF NOT EXISTS u_domains__archiveHost ON c_domains (json_extract(data, '$.archiveHost') ASC);
CREATE INDEX IF NOT EXISTS i_domains__accountId__createdAt ON c_domains (accountId ASC, json_extract(data, '$.createdAt') ASC);
