CREATE INDEX IF NOT EXISTS i_events__accountId ON c_events (accountId);
CREATE INDEX IF NOT EXISTS i_events__providerMessageId ON c_events (json_extract(data, '$.providerMessageId') ASC);
CREATE INDEX IF NOT EXISTS i_events__campaignId__type ON c_events (json_extract(data, '$.campaignId') ASC, json_extract(data, '$.type') ASC);
CREATE INDEX IF NOT EXISTS i_events__accountId__occurredAt_d ON c_events (accountId ASC, json_extract(data, '$.occurredAt') DESC);
CREATE UNIQUE INDEX IF NOT EXISTS u_events__providerEventId ON c_events (json_extract(data, '$.providerEventId') ASC) WHERE json_type(data, '$.providerEventId') = 'text';
CREATE TABLE IF NOT EXISTS c_globalsuppressions (_id TEXT PRIMARY KEY NOT NULL, accountId TEXT, data TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS i_globalsuppressions__accountId ON c_globalsuppressions (accountId);
CREATE UNIQUE INDEX IF NOT EXISTS u_globalsuppressions__emailHash ON c_globalsuppressions (json_extract(data, '$.emailHash') ASC);
CREATE INDEX IF NOT EXISTS i_globalsuppressions__reason__expiresAt ON c_globalsuppressions (json_extract(data, '$.reason') ASC, json_extract(data, '$.expiresAt') ASC);
CREATE TABLE IF NOT EXISTS c_messages (_id TEXT PRIMARY KEY NOT NULL, accountId TEXT, data TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS i_messages__accountId ON c_messages (accountId);
CREATE UNIQUE INDEX IF NOT EXISTS u_messages__campaignId__contactId ON c_messages (json_extract(data, '$.campaignId') ASC, json_extract(data, '$.contactId') ASC) WHERE json_extract(data, '$.kind') = 'campaign';
CREATE UNIQUE INDEX IF NOT EXISTS u_messages__campaignId__contactId__kind ON c_messages (json_extract(data, '$.campaignId') ASC, json_extract(data, '$.contactId') ASC, json_extract(data, '$.kind') ASC) WHERE json_extract(data, '$.kind') = 'last-chance';
CREATE INDEX IF NOT EXISTS i_messages__providerMessageId ON c_messages (json_extract(data, '$.providerMessageId') ASC) WHERE json_extract(data, '$.providerMessageId') IS NOT NULL;
CREATE INDEX IF NOT EXISTS i_messages__kind__createdAt_d ON c_messages (json_extract(data, '$.kind') ASC, json_extract(data, '$.createdAt') DESC);
CREATE INDEX IF NOT EXISTS i_messages__newsletterId__sentAt ON c_messages (json_extract(data, '$.newsletterId') ASC, json_extract(data, '$.sentAt') ASC);
CREATE INDEX IF NOT EXISTS i_messages__campaignId__status ON c_messages (json_extract(data, '$.campaignId') ASC, json_extract(data, '$.status') ASC);
CREATE INDEX IF NOT EXISTS i_messages__accountId__campaignId ON c_messages (accountId ASC, json_extract(data, '$.campaignId') ASC) WHERE json_extract(data, '$.status') = 'queued';
CREATE INDEX IF NOT EXISTS i_messages__accountId__sentAt_d ON c_messages (accountId ASC, json_extract(data, '$.sentAt') DESC);
